mapper.select:
WITH temp_table AS (
SELECT #{item,jdbcType=VARCHAR} sap_code FROM dual
) select
from T_LH_MONTH_STOCK where sap_code IN ( select sap_code from temp_table) and del_flag = '0' AND stock_month BETWEEN STR_TO_DATE(#{stockMonth,jdbcType=VARCHAR}, '%Y-%m' ) AND last_day( STR_TO_DATE(#{stockMonth,jdbcType=VARCHAR}, '%Y-%m' ) )

mapper.update:
merge into T_LH_MONTH_STOCK a USING (
select #{ITEM.stockMonth,jdbcType=DATE} stock_month, #{ITEM.sapCode,jdbcType=VARCHAR} sap_code, #{ITEM.stockNum,jdbcType=DECIMAL} stock_num, #{ITEM.createBy,jdbcType=VARCHAR} create_by, #{ITEM.createTime,jdbcType=DATE} create_time, #{ITEM.updateBy,jdbcType=VARCHAR} update_by, #{ITEM.updateTime,jdbcType=DATE} update_time, #{ITEM.remark,jdbcType=VARCHAR} remark from dual
) b ON (a.stock_month = b.stock_month and a.sap_code = b.sap_code and a.del_flag = '0') WHEN MATCHED THEN UPDATE SET a.stock_num = b.stock_num, a.update_by = b.create_by, a.update_time = now(), a.remark = b.remark WHEN NOT MATCHED THEN INSERT ( a.id , a.stock_month, a.sap_code, a.stock_num , a.create_by , a.create_time , a.remark, a.del_flag ) values (SEQ_NC_STOCK.NEXTVAL, b.stock_month, b.sap_code, b.stock_num, b.create_by, now(), b.remark, '0' )
